class Solution
{
public:
    int minCost(vector< vector< int >>& costs)
    {
        int a = 0, b = 0, c = 0;
        for (auto&v : costs)
        {
            int x = v[0] + min(b, c), y = v[1] + min(a, c), z = v[2] + min(a, b);
            a = x;
            b = y;
            c = z;
        }
        return min( { a, b, c });
    }
};
